22	declare_lint_rule! {
23	    /// Detect return type annotations that are misleadingly wider than what
24	    /// the implementation actually returns.
25	    ///
26	    /// Reports when a function's explicit return type annotation is wider than
27	    /// what TypeScript would infer from the implementation, hiding precise types
28	    /// from callers.
29	    ///
30	    /// ## Examples
31	    ///
32	    /// ### Invalid
33	    ///
34	    /// ```ts,expect_diagnostic,file=invalid.ts
35	    /// function getStatus(b: boolean): string { if (b) return "loading"; return "idle"; }
36	    /// ```
37	    ///
38	    /// ```ts,expect_diagnostic,file=invalid2.ts
39	    /// function getCode(ok: boolean): number { if (ok) return 200; return 404; }
40	    /// ```
41	    ///
42	    /// ```ts,expect_diagnostic,file=invalid3.ts
43	    /// class Foo { getStatus(b: boolean): string { if (b) return "loading"; return "idle"; } }
44	    /// ```
45	    ///
46	    /// ```ts,expect_diagnostic,file=invalid4.ts
47	    /// const obj = { getMode(b: boolean): string { if (b) return "dark"; return "light"; } };
48	    /// ```
49	    ///
50	    /// ```ts,expect_diagnostic,file=invalid5.ts
51	    /// function makeData(): object { return { retry: true }; }
52	    /// ```
53	    ///
54	    /// ### Valid
55	    ///
56	    /// ```ts
57	    /// function getStatus() { return "loading"; }
58	    /// ```
59	    ///
60	    /// ```ts
61	    /// function run(): void { return; }
62	    /// ```
63	    ///
64	    /// ```ts
65	    /// class Foo { greet(): string { return "hello"; } }
66	    /// ```
67	    ///
68	    /// ## Known limitations
69	    ///
70	    /// When a return uses a type assertion such as `as T`, the rule does
71	    /// not flag the return unless it can prove that `T` is narrower than
72	    /// `object`. Trusted cases include `unknown`, `any`, `typeof` queries,
73	    /// conditional types, generic type parameters, and types the rule
74	    /// cannot resolve. Intersections (`A & B`) are trusted when every
75	    /// member is or when any member is `any`; unions (`A | B`) when at
76	    /// least one is.
77	    pub NoMisleadingReturnType {
78	        version: "2.4.11",
79	        name: "noMisleadingReturnType",
80	        language: "ts",
81	        recommended: false,
82	        domains: &[RuleDomain::Types],
83	        issue_number: Some("9810"),
84	    }
85	}
